    &quot;MATCH (x:%s) &lt;-[r]- (m:%s) &quot;
        + &quot;WHERE NOT (x)&lt;-[:PREDECESSOR]-() &quot;
        + &quot;AND NOT (x)-[:PREDECESSOR {action:&#39;DEL&#39;}]-&gt;() &quot;
        + &quot;AND NOT (m)-[:PREDECESSOR {action:&#39;DEL&#39;}]-&gt;() &quot;
